import sys

def main():
    input = sys.stdin.buffer.readline
    n = int(input())
    points = [tuple(map(int, input().split())) for _ in range(n)]

    # For each ball k, mark the balls that it removes when chosen.
    removes = [0] * n
    for k, (xk, yk) in enumerate(points):
        mask = 0
        for i, (x, y) in enumerate(points):
            if (x < xk and y < yk) or (x > xk and y > yk):
                mask |= 1 << i
        removes[k] = mask

    seen = { (1 << n) - 1 }
    stack = [(1 << n) - 1]

    while stack:
        state = stack.pop()
        remaining = state
        while remaining:
            bit = remaining & -remaining
            remaining -= bit
            k = bit.bit_length() - 1
            nxt = state & ~(removes[k] & state)
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)

    print(len(seen) % 998244353)

if __name__ == "__main__":
    main()

import sys
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    n,m=data[:2]
    INF=n+1
    # For each X and each L, store minimum R of a condition with that X and L.
    need=[[INF]*(n+2) for _ in range(n+1)]
    j=2
    for _ in range(m):
        l,r,x=data[j:j+3]
        j+=3
        if r<need[x][l]:
            need[x][l]=r
    # need[x][a] = minimum R among conditions with X=x and L>=a.
    for x in range(1,n+1):
        for a in range(n-1,0,-1):
            need[x][a]=min(need[x][a],need[x][a+1])

    dp=[[0]*(n+2) for _ in range(n+2)]
    for a in range(1,n+2):
        dp[a][a-1]=1
    for length in range(1,n+1):
        for a in range(1,n-length+2):
            b=a+length-1
            total=0
            for k in range(a,b+1):
                # A condition fails exactly when its whole interval lies in
                # [a,b] and contains k with X=k.
                if need[k][a]>b:
                    total += dp[a][k-1]*dp[k+1][b]
            dp[a][b]=total%MOD
    print(dp[1][n])

if __name__=='__main__':
    main()

