import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]

    primes = set()
    for a in arr:
        x = a
        d = 2
        while d * d <= x:
            if x % d == 0:
                primes.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            primes.add(x)

    answer = 1
    for p in primes:
        exponents = [0] * (n - 1)
        for i, a in enumerate(arr):
            x = a
            d = 2
            while d * d <= x:
                if x % d == 0:
                    count = 0
                    while x % d == 0:
                        x //= d
                        count += 1
                    if d == p:
                        exponents[i] = count
                d += 1
            if x > 1 and x == p:
                exponents[i] = 1

        total = sum(exponents)
        if total == 0:
            continue

        powers = [pow(p, h, MOD) for h in range(total + 1)]
        # Paths that have not visited height 0, and paths that have.
        not_hit = [0] * (total + 1)
        hit = [0] * (total + 1)
        for h in range(total + 1):
            if h == 0:
                hit[h] = powers[h]
            else:
                not_hit[h] = powers[h]

        for step in exponents:
            next_not = [0] * (total + 1)
            next_hit = [0] * (total + 1)
            for h in range(total + 1):
                destinations = (h + step,) if step == 0 else (h + step, h - step)
                value = not_hit[h]
                if value:
                    for dest in destinations:
                        if 0 <= dest <= total:
                            next_not[dest] = (next_not[dest] + value * powers[dest]) % MOD
                value = hit[h]
                if value:
                    for dest in destinations:
                        if 0 <= dest <= total:
                            next_hit[dest] = (next_hit[dest] + value * powers[dest]) % MOD

            # A previously untouched path becomes touched when it first reaches 0.
            next_hit[0] = (next_hit[0] + next_not[0]) % MOD
            next_not[0] = 0
            not_hit, hit = next_not, next_hit

        answer = answer * (sum(hit) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

