import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]
    limit = 100000

    # Euler's totient function, used in gcd(x, y) = sum_{d | gcd(x,y)} phi(d).
    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if phi[p] == p:
            for multiple in range(p, limit + 1, p):
                phi[multiple] -= phi[multiple] // p

    divisors = [[] for _ in range(limit + 1)]
    for d in range(1, limit + 1):
        for multiple in range(d, limit + 1, d):
            divisors[multiple].append(d)

    # weighted[d] = sum of 2^(i-1) over prior indices i with d | A_i
    weighted = [0] * (limit + 1)
    answer = 0
    index_weight = 1
    output = []

    for x in values:
        ending = 0
        for d in divisors[x]:
            ending += phi[d] * weighted[d]
        ending %= MOD

        # Existing pairs acquire two choices (selected or not) for the new item;
        # ending is the contribution of pairs whose right endpoint is this item.
        answer = (2 * answer + ending) % MOD
        for d in divisors[x]:
            weighted[d] = (weighted[d] + index_weight) % MOD

        output.append(str(answer))
        index_weight = index_weight * 2 % MOD

    sys.stdout.write("\n".join(output))


if __name__ == "__main__":
    main()

