from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        best1 = best2 = 0
        owner = -1
        gain = [0] * len(conflictingPairs)
        total = 0

        for r in range(1, n + 1):
            for a, idx in by_right[r]:
                if a > best1:
                    best2 = best1
                    best1 = a
                    owner = idx
                elif a > best2:
                    best2 = a
            total += r - best1
            if owner != -1:
                gain[owner] += best1 - best2

        return total + max(gain)

