import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    it=iter(data)
    n=next(it); m=next(it); q=next(it)
    edges=[]
    for _ in range(m):
        edges.append((next(it)-1,next(it)-1,next(it)))
    queries=[]
    deleted=[False]*m
    for _ in range(q):
        t=next(it)
        if t==1:
            i=next(it)-1
            deleted[i]=True
            queries.append((1,i))
        else:
            queries.append((2,next(it)-1,next(it)-1))

    inf=10**30
    d=[[inf]*n for _ in range(n)]
    for i in range(n):
        d[i][i]=0
    for i,(a,b,c) in enumerate(edges):
        if not deleted[i]:
            d[a][b]=d[b][a]=c

    # APSP in the graph after all closures.
    for k in range(n):
        dk=d[k]
        for i in range(n):
            dik=d[i][k]
            if dik==inf:
                continue
            row=d[i]
            for j in range(n):
                candidate=dik+dk[j]
                if candidate<row[j]:
                    row[j]=candidate

    answers=[]
    for query in reversed(queries):
        if query[0]==2:
            value=d[query[1]][query[2]]
            answers.append(str(-1 if value>=inf else value))
        else:
            a,b,c=edges[query[1]]
            # Add this road. Any new shortest path uses it at most once;
            # the distances on the right-hand side are from before insertion.
            row_a=d[a][:]
            row_b=d[b][:]
            col_a=[d[i][a] for i in range(n)]
            col_b=[d[i][b] for i in range(n)]
            for i in range(n):
                via_a=col_a[i]+c
                via_b=col_b[i]+c
                row=d[i]
                for j in range(n):
                    candidate=via_a+row_b[j]
                    if candidate<row[j]:
                        row[j]=candidate
                    candidate=via_b+row_a[j]
                    if candidate<row[j]:
                        row[j]=candidate
    print('\n'.join(reversed(answers)))

if __name__=='__main__':
    main()

