import sys

def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    t = next(it)
    out = []
    for _ in range(t):
        n, m = next(it), next(it)
        boxes = [(next(it), next(it)) for _ in range(n)]
        # A box can be profitably used only after serving all of its capacity;
        # use the best available net return across the adversarial types.
        if m == 1:
            ans = 0
        else:
            ans = max(0, max(v-p for v,p in boxes))
        out.append(str(ans))
    print('\n'.join(out))

if __name__ == '__main__':
    solve()

