    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        g = gcd(a, b)
        processes.append((a, p, b, q, g))

    def feasible(target):
        total_cost = 0
        for a, p, b, q, g in processes:
            if p * (b // g) >= q * (a // g):
                # Any block of b/g S machines can be replaced by a/g T machines.
                best = 10**30
                for s in range(b // g):
                    remaining = target - a * s
                    t = max(0, (remaining + b - 1) // b)
                    cost = s * p + t * q
                    if cost < best:
                        best = cost
            else:
                # Symmetrically, an optimal solution needs fewer than a/g T machines.
                best = 10**30
                for t in range(a // g):
                    remaining = target - b * t
                    s = max(0, (remaining + a - 1) // a)
                    cost = t * q + s * p
                    if cost < best:
                        best = cost
            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


