class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        dp = [1]

        for i in range(1, n + 1):
            limit = min(i, x)
            ndp = [0] * (limit + 1)
            for k in range(limit + 1):
                # A performer joins one of k already occupied stages.
                if k < len(dp):
                    ndp[k] += k * dp[k]
                # Or starts a new stage, whose score can be chosen in y ways.
                if k > 0 and k - 1 < len(dp):
                    ndp[k] += (x - k + 1) * y * dp[k - 1]
                ndp[k] %= mod
            dp = ndp

        return sum(dp) % mod

