class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Pascal's triangle gives the number of suffixes with each number
        # of set bits.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for length in range(1, n + 1):
            comb[length][0] = comb[length][length] = 1
            for ones in range(1, length):
                comb[length][ones] = (
                    comb[length - 1][ones - 1] + comb[length - 1][ones]
                ) % MOD

        # Count strings strictly smaller than s, grouped by popcount.
        counts = [0] * (n + 1)
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for extra_ones in range(remaining + 1):
                    total_ones = prefix_ones + extra_ones
                    counts[total_ones] = (
                        counts[total_ones] + comb[remaining][extra_ones]
                    ) % MOD
                prefix_ones += 1

        answer = 0
        for ones in range(1, n + 1):
            value = ones
            reductions = 0
            while value > 1:
                value = value.bit_count()
                reductions += 1
            # A number with `ones` set bits takes one operation to reach ones.
            if reductions + 1 <= k:
                answer = (answer + counts[ones]) % MOD

        return answer

