from collections import deque

def solve():
    data=sys.stdin.buffer.read().split()
    if not data:return
    n=int(data[0]); rows=data[1:]
    # lists indexed by vertex and character
    inc=[[[] for _ in range(26)] for _ in range(n)]
    out=[[[] for _ in range(26)] for _ in range(n)]
    d=[[-1]*n for _ in range(n)]
    q=deque()
    for i in range(n):
        d[i][i]=0;q.append((i,i))
    for i,row in enumerate(rows):
        for j,ch in enumerate(row):
            if ch!=45:
                c=ch-97
                out[i][c].append(j);inc[j][c].append(i)
                if d[i][j]<0:
                    d[i][j]=1;q.append((i,j))
    left= n*n-sum(1 for i in range(n) for j in range(n) if d[i][j]>=0)
    while q and left:
        u,v=q.popleft(); nd=d[u][v]+2
        for c in range(26):
            a=inc[u][c]; b=out[v][c]
            if a and b:
                for x in a:
                    dx=d[x]
                    for y in b:
                        if dx[y]<0:
                            dx[y]=nd;q.append((x,y));left-=1
    sys.stdout.write('\n'.join(' '.join(map(str,r)) for r in d))
