lo, hi = 0, 1_000_001
while hi - lo > 1:
    mid = (lo + hi) // 2
    if mid * mid * mid <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d:
        continue
    # N/d = 3*y^2 + 3*d*y + d^2
    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue
    s = math.isqrt(disc)
    if s * s != disc:
        continue
    numerator = s - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        x = y + d
        if x**3 - y**3 == N:
            print(x, y)
            break
else:
