import sys
from bisect import bisect_left

def main():
    data=sys.stdin.buffer.read().split()
    if not data: return
    n,q=map(int,data[:2]); s=data[2].decode()
    ones=[]; twos=[]; slashes=[]
    for i,c in enumerate(s):
        if c=='1': ones.append(i)
        elif c=='2': twos.append(i)
        else: slashes.append(i)
    out=[]; j=3
    for _ in range(q):
        L=int(data[j])-1; R=int(data[j+1]); j+=2  # half-open [L,R)
        start=bisect_left(ones,L)
        end=bisect_left(twos,R)
        def good(k):
            if k==0:
                x=bisect_left(slashes,L)
                return x<len(slashes) and slashes[x]<R
            oi=start+k-1
            ti=end-k
            if oi>=len(ones) or ti<0:
                return False
            a=ones[oi]+1
            b=twos[ti]-1
            if a>b: return False
            x=bisect_left(slashes,a)
            return x<len(slashes) and slashes[x]<=b
        lo=-1; hi=(R-L-1)//2+1
        while hi-lo>1:
            mid=(lo+hi)//2
            if good(mid): lo=mid
            else: hi=mid
        out.append(str(2*lo+1 if lo>=0 else 0))
    sys.stdout.write('\n'.join(out))
