from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise directions in image coordinates: SE, SW, NW, NE.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # straight[d][e][r][c]: longest straight matching sequence from this
        # cell, where e=0 expects 2 and e=1 expects 0.
        straight = [[[[0] * m for _ in range(n)] for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    for e, value in ((0, 2), (1, 0)):
                        if grid[r][c] == value:
                            nr, nc = r + dr, c + dc
                            continuation = (
                                straight[d][1 - e][nr][nc]
                                if 0 <= nr < n and 0 <= nc < m else 0
                            )
                            straight[d][e][r][c] = 1 + continuation

        answer = 0
        for d, (dr, dc) in enumerate(dirs):
            clockwise = (d + 1) % 4
            trd, tcd = dirs[clockwise]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)

            # one_turn: matching segment starting here, with a turn still allowed
            one_turn = [[[0] * m for _ in range(n)] for _ in range(2)]
            for r in rows:
                for c in cols:
                    for e, value in ((0, 2), (1, 0)):
                        if grid[r][c] != value:
                            continue
                        best = 0
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = one_turn[1 - e][nr][nc]
                        nr, nc = r + trd, c + tcd
                        if 0 <= nr < n and 0 <= nc < m:
                            best = max(best, straight[clockwise][1 - e][nr][nc])
                        one_turn[e][r][c] = 1 + best

            for r in range(n):
                for c in range(m):
                    if grid[r][c] == 1:
                        answer = max(answer, 1)
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                            answer = max(answer, 1 + one_turn[0][nr][nc])

        return answer

