class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # powers[i] is 10**i modulo k
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        # The digit at half-position j contributes this coefficient to the
        # complete palindrome's value modulo k.
        coeff = []
        for j in range(m):
            mirror = n - 1 - j
            if j == mirror:
                coeff.append(powers[j])
            else:
                coeff.append((powers[j] + powers[mirror]) % k)

        # can[j][r] indicates whether positions j..m-1 can contribute
        # residue r modulo k.
        can = [None] * (m + 1)
        can[m] = bytearray([1] + [0] * (k - 1))
        for j in range(m - 1, -1, -1):
            nxt = can[j + 1]
            cur = bytearray(k)
            c = coeff[j]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * c) % k]:
                        cur[r] = 1
                        break
            can[j] = cur

        # Greedily choose the largest feasible digit at each half-position.
        digits = []
        rem = 0
        for j in range(m):
            low = 1 if j == 0 else 0
            for d in range(9, low - 1, -1):
                new_rem = (rem + d * coeff[j]) % k
                if can[j + 1][(-new_rem) % k]:
                    digits.append(str(d))
                    rem = new_rem
                    break

        half = ''.join(digits)
        if n % 2:
            return half + half[-2::-1]
        return half + half[::-1]

