class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        nxt=[n]*n
        st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]] <= nums[i]: st.pop()
            nxt[i]=st[-1] if st else n
            st.append(i)
        levels=n.bit_length()
        up=[array('i', nxt)]
        agg=[array('q', (nums[i]*(nxt[i]-i) for i in range(n)))]
        for p in range(1,levels):
            pu=up[-1]; pa=agg[-1]
            nu=array('i',[n])*n
            na=array('q',[0])*n
            for i in range(n):
                mid=pu[i]
                if mid<n:
                    nu[i]=pu[mid]
                    na[i]=pa[i]+pa[mid]
                else:
                    nu[i]=n
                    na[i]=pa[i]
            up.append(nu); agg.append(na)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
        def cost(l,r):
            node=l; total=0
            for p in range(levels-1,-1,-1):
                dest=up[p][node]
                if dest<=r:
                    total+=agg[p][node]
                    node=dest
            total+=nums[node]*(r-node+1)
            return total-(pref[r+1]-pref[l])
        ans=0; left=0
        for r in range(n):
            while left<=r and cost(left,r)>k: left+=1
            ans+=r-left+1
        return ans

