class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        a = [Counter(s).get(chr(97+i), 0) for i in range(26)]
        n = len(s)
        ans = n
        # For a chosen common frequency, process the alphabet while tracking
        # characters shifted from the preceding letter.
        for k in range(1, max(a) + 1):
            inf = 10**9
            dp = [0]
            for c in a:
                # dp[x] is the minimum cost with x characters arriving here.
                # Choosing a final count of zero or k, and sending y onward,
                # costs the local insertions/deletions plus y shifts.
                nd = [inf] * (n + 1)
                for x, base in enumerate(dp):
                    if base >= inf:
                        continue
                    available = c + x
                    for target in (0, k):
                        # A useful outgoing flow need never exceed available.
                        for y in range(min(available, n) + 1):
                            cost = base + abs(available - y - target) + y
                            if cost < nd[y]:
                                nd[y] = cost
                dp = nd
            ans = min(ans, min(dp))
        return ans

