from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first = p.find('*')
        second = p.find('*', first + 1)
        parts = [p[:first], p[first + 1:second], p[second + 1:]]
        n = len(s)

        def occurrences(word):
            if not word:
                return list(range(n + 1))
            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                    pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        a, b, c = map(occurrences, parts)
        la, lb, lc = map(len, parts)
        ans = n + 1
        for pos in b:
            ix = bisect_right(a, pos - la) - 1
            if ix < 0:
                continue
            iy = bisect_left(c, pos + lb)
            if iy == len(c):
                continue
            ans = min(ans, c[iy] + lc - a[ix])
        return -1 if ans == n + 1 else ans

