import sys

def solve_case(n, a, b):
    xs = [i for i, c in enumerate(a) if c == '1']
    ys = [i for i, c in enumerate(b) if c == '1']
    if len(xs) < len(ys):
        return -1

    def feasible(d):
        # Ordered assignment: every target must receive a source, and every
        # source must be assigned to some target within distance d.
        j = 0
        last = len(ys) - 1
        for x in xs:
            while j < last and abs(x - ys[j + 1]) <= d:
                # Advance only when the current target has already received
                # a source; handled by the greedy frontier below.
                break
            # Greedily use the earliest target which can still be covered.
            if j < len(ys) and abs(x - ys[j]) <= d:
                # If this source can serve a later target and the present
                # target is already covered, defer it to the later target.
                if j + 1 < len(ys) and abs(x - ys[j + 1]) <= d:
                    j += 1
                else:
                    pass
            else:
                return False
        return j == len(ys) - 1

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

