from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        chars = []
        order = []
        left = [0] * n
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if not done:
                left[v] = len(chars)
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))
            else:
                chars.append(s[v])
                order.append(v)

        text = ''.join(chars)

        # Manacher radii for odd-length and even-length palindromes.
        odd = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        size = [1] * n
        for v in order:
            if parent[v] != -1:
                size[parent[v]] += size[v]

        answer = [False] * n
        for v in range(n):
            length = size[v]
            start = left[v]
            end = start + length - 1
            if length % 2:
                center = (start + end) // 2
                answer[v] = odd[center] >= length // 2 + 1
            else:
                center = (start + end + 1) // 2
                answer[v] = even[center] >= length // 2
        return answer

