class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For each prefix index residue modulo k, keep the smallest
        # earlier prefix sum. Subtracting it maximizes a valid subarray.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        answer = None

        for i, value in enumerate(nums, 1):
            prefix += value
            r = i % k
            smallest = min_prefix[r]

            if smallest is not None:
                candidate = prefix - smallest
                if answer is None or candidate > answer:
                    answer = candidate

            if smallest is None or prefix < smallest:
                min_prefix[r] = prefix

        return answer

