import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        width = len(str(n))
        limit = 10 ** width

        # Sieve primes among all values with this digit width.
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        lower = 10 ** (width - 1)
        dist = {n: n}  # Include the starting value in the total cost.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            digits = list(map(int, str(value)))
            for i, digit in enumerate(digits):
                place = 10 ** (width - 1 - i)
                for change in (-1, 1):
                    new_digit = digit + change
                    if not 0 <= new_digit <= 9:
                        continue
                    if i == 0 and new_digit == 0:
                        continue
                    nxt = value + change * place
                    if is_prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < dist.get(nxt, float('inf')):
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))

        return -1

