from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        target = set(targetIndices)
        m = len(pattern)
        inf = len(targetIndices) + 1
        # dp[j] is the minimum number of target positions kept to match
        # the first j characters of pattern in the processed source prefix.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            keep_cost = 1 if i in target else 0
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] != inf:
                    dp[j + 1] = min(dp[j + 1], dp[j] + keep_cost)

        return len(targetIndices) - dp[m]

