class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {tuple(point) for point in points}
        answer = -1

        for x1, y1 in point_set:
            for x2, y2 in point_set:
                if x1 >= x2 or y1 >= y2:
                    continue

                corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
                if not corners.issubset(point_set):
                    continue

                # Every point in the closed rectangle must be one of its corners.
                if all(
                    (x, y) in corners
                    or not (x1 <= x <= x2 and y1 <= y <= y2)
                    for x, y in point_set
                ):
                    answer = max(answer, (x2 - x1) * (y2 - y1))

        return answer

